/** Representative publications generated by the same exporter as the browser. */
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { buildEpub } from '../dist/export.js';
import { sampleProject } from '../dist/editorial.js';

const PNG = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGNgYGD4DwABBAEAX+XDSwAAAABJRU5ErkJggg==';
const base = { id: 'standards-fixture', title: '문장과 그림으로 보는 세계', author: '검증 작가', language: 'ko', theme: 'sage', updatedAt: '2026-10-20T00:00:00.000Z' };
const diagram = type => '```folio-diagram\n' + JSON.stringify({ type, title: '계절의 변화', caption: '표의 수치와 같은 값입니다.', labels: ['봄', '여름', '가을'], values: [12, -20, 0], unit: '개', evidence: ['봄 12개', '여름 -20개', '가을 0개'], columns: ['계절', '기록'], rows: [['봄', '싹'], ['여름', '잎']] }) + '\n```';

export function epubFixtureProjects() {
  return [
    ['sample', { ...sampleProject(), updatedAt: base.updatedAt }],
    ['korean-prose', { ...base, title: '한글 & <문장> “기록”', chapters: [
      { title: '처음의 마음', content: '# 소제목\n\n**소중한 문장**과 *고요한 순간*.\n둘째 줄입니다.\n\n> 마음이 머무는 자리\n\n- 하나\n- 둘\n\n1. 첫째\n2. 둘째\n\n`코드`와 [안전한 링크](https://example.org/?a=1&b=2).' },
      { title: '다음의 이야기', content: '한국어 단락.\n\n```html\n<script>원고에 포함한 코드 예제</script>\n```' },
    ] }],
    ['tables-diagrams', { ...base, chapters: [{ title: '표와 도표', content: '| 항목 | 설명 |\n| :--- | ---: |\n| **표** | A\\|B |\n\n' + ['table', 'flow', 'bar', 'line'].map(diagram).join('\n\n') }] }],
    ['image-cover', { ...base, coverBackground: { src: PNG, alt: '표지의 어두운 점' }, coverDesign: { source: 'background', fit: 'contain', position: 'bottom', overlay: 50, textColor: 'light', layout: 'center' }, chapters: [{ title: '그림이 있는 장', image: { src: PNG, alt: '어두운 점', caption: '테스트용 PNG 삽화' }, figures: [{ id: 'dot', src: PNG, alt: '어두운 점의 확대', caption: '본문의 그림 설명' }], content: '그림 앞의 문장.\n\n![어두운 점의 확대](folio-asset:dot)\n\n그림 뒤의 문장.' }] }],
    ['publication-metadata', { ...base, publication: { publisher: '폴리오 출판', rightsHolder: '검증 작가', publicationDate: '2026-10-20', isbn: '9780306406157' }, chapters: [{ title: '본문', content: '출판 메타데이터와 판권 검증.' }, { title: '판권', content: '지은이: 검증 작가\n\n발행처: 폴리오 출판' }] }],
    ['empty-book', { ...base, chapters: [] }],
  ];
}

export async function writeEpubFixtures(directory) {
  await mkdir(directory, { recursive: true });
  const files = [];
  for (const [name, project] of epubFixtureProjects()) {
    const file = join(directory, `${name}.epub`);
    await writeFile(file, await buildEpub(project));
    files.push(file);
  }
  return files;
}
